mapper.select:
select m.id, m.title, m.description, m.status, m.progress, m.dead_line, m.priority, m.create_dept, m.create_by, m.create_time, m.update_by, m.update_time, m.deleted_flag, m.tenant_id from mes_rec_task m
m.deleted_flag = 0 and m.user_id = #{param.userId}
and m.id = #{param.id}
and m.title like concat('%', #{param.title}, '%')
and m.status = #{param.status}
and m.dead_line >= #{param.beginDeadLine}
and #{param.endDeadLine} > m.dead_line
order by m.update_time desc
